<script setup lang="ts">import type {Ad} from '@/domain/types';import {assetUrl} from '@/services/api';defineProps<{ad:Ad}>();const emit=defineEmits<{open:[ad:Ad]}>();</script><template><view class="ad-spot" @click="emit('open',ad)"><video v-if="ad.media==='video'" :src="assetUrl(ad.asset)" controls :autoplay="false"/><image v-else :src="assetUrl(ad.asset)" mode="aspectFit"/><text class="label">广告</text><text class="name">{{ad.name}}</text></view></template><style scoped>.ad-spot{position:relative;margin:12px 14px;border-radius:8px;overflow:hidden;background:#ffffff08;height:116px;cursor:pointer}.ad-spot image,.ad-spot video{width:100%;height:100%}.label{position:absolute;right:5px;top:5px;color:#fff;background:#0008;font-size:9px;padding:2px 5px}.name{position:absolute;left:8px;bottom:5px;font-size:10px;color:#fff;text-shadow:0 1px 2px #000}</style>